<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_module('budget');$pageTitle='Budget Categories';$activeMenu='budget-categories';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$desc=trim($_POST['description']??'');if($name){if(!empty($_POST['id'])){$s=db()->prepare('UPDATE budget_categories SET name=?,description=? WHERE id=?');$s->execute([$name,$desc,(int)$_POST['id']]);log_activity('UPDATE','Budget Category','Updated '.$name);}else{$s=db()->prepare('INSERT INTO budget_categories(name,description) VALUES(?,?)');$s->execute([$name,$desc]);log_activity('CREATE','Budget Category','Created '.$name);}flash('success','Budget category saved.');redirect('budget/categories.php');}}
if(isset($_GET['toggle'])){require_role(['Administrator','Finance Manager']);if(!hash_equals(csrf_token(),$_GET['token']??'')){http_response_code(419);exit('Invalid CSRF token.');}$id=(int)$_GET['toggle'];db()->prepare('UPDATE budget_categories SET is_active=1-is_active WHERE id=?')->execute([$id]);flash('success','Category status changed.');redirect('budget/categories.php');}
$rows=db()->query('SELECT c.*,(SELECT COUNT(*) FROM budgets b WHERE b.category_id=c.id) usage_count FROM budget_categories c ORDER BY c.name')->fetchAll();require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><h1>Budget Categories</h1><p>Maintain the chart of budget classifications used across allocations and expenses.</p></div></div><div class="row g-3"><div class="col-lg-4"><div class="card-panel"><div class="card-head"><h2 class="section-title">Add Category</h2></div><div class="card-body"><form method="post"><?=csrf_field()?><div class="mb-3"><label class="form-label">Category Name</label><input class="form-control" name="name" required></div><div class="mb-3"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="4"></textarea></div><button class="btn btn-primary">Save Category</button></form></div></div></div><div class="col-lg-8"><div class="card-panel"><div class="card-body"><div class="table-responsive"><table class="table data-table"><thead><tr><th>Name</th><th>Description</th><th>Budgets</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td class="fw-semibold"><?=e($r['name'])?></td><td><?=e($r['description'])?></td><td><?=(int)$r['usage_count']?></td><td><?=status_badge($r['is_active']?'Active':'Inactive')?></td><td><?php if(has_role(['Administrator','Finance Manager'])):?><a class="btn btn-sm btn-light border" href="<?=e(url('budget/categories.php?toggle='.$r['id'].'&token='.csrf_token()))?>">Toggle</a><?php else:?><span class="text-secondary">—</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div></div></div><?php require ROOT_PATH.'/includes/footer.php';?>
